const $=s=>document.querySelector(s),KEY='lived-history-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.version!==1)state=INITIAL();}catch{state=INITIAL();}let screen='home',studyTab='review',activeQ=0,quizMode='chapter',selected=null,modal=null;const statNames={health:'체력',knowledge:'지식',fame:'명성',wealth:'재산'},relationNames={village:'마을 주민',merchant:'상단',royal:'왕건 세력'};
const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',era:'M3 6l6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15',study:'M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1z M12 5v16',records:'M5 3h14v18H5z M9 8h6 M9 12h6 M9 16h4',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',lock:'M6 10h12v11H6z M8 10V6a4 4 0 018 0v4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const percent=()=>state.completed?100:Math.min(95,Math.round(state.visited.length/20*100));const understanding=()=>Math.round(Object.values(state.answers).filter(Boolean).length/QUESTIONS.length*100);const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('저장 공간을 사용할 수 없습니다. 브라우저 설정을 확인해 주세요.');}};
function toast(t){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),2600)}
function shell(content){const tab=['game','history','quiz','complete','teaser'].includes(screen)?'home':screen;return `<div class="shell"><aside class="sidebar"><div class="brand">살아본 한국사<small>HISTORY, LIVED.</small></div><nav class="nav" aria-label="주 메뉴">${[['home','홈'],['era','시대'],['study','공부'],['records','내 기록']].map(([id,label])=>`<button data-nav="${id}" class="${tab===id?'active':''}">${icon(id)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-foot"><b>역사 속, 나의 이야기</b>외우는 역사에서<br>살아보는 역사로.<br><span style="display:block;margin-top:15px;letter-spacing:2px;font-size:10px">CHAPTER 01 · GORYEO</span></div></aside><main class="main fade">${content}</main></div>${modal?modalHTML():''}`}
function pageHeader(title,sub='YOUR HISTORY, YOUR STORY'){return `<header class="topbar"><div><div class="eyebrow">${sub}</div><h1>${title}</h1></div><div class="toptools"><span>나의 첫 번째 역사 여행</span><button class="avatar" data-action="status" aria-label="내 상태 보기">나</button></div></header>`}
function home(){return pageHeader('오늘은 어떤 역사를 살아볼까요?')+`<section class="hero"><div class="hero-content"><span class="pill">EPISODE 01 · 918 — 1392</span><h2><span>눈떠보니</span>고려</h2><p>눈을 뜨니, 교과서 속 세상이다.<br>새로운 나라의 시작에서 나의 이야기가 시작된다.</p><div class="hero-bottom"><button class="primary" data-action="play">${state.started?'이야기 이어하기':'새로운 이야기 시작'}</button><small>CH.01 &nbsp; 918년, 새로운 나라</small></div></div><span class="hero-mark">당신의 선택이 역사가 되는 순간</span></section><div class="home-grid"><section><div class="section-title"><h2>나의 고려 이야기</h2><button class="text-btn" data-nav="records">기록 보기 &nbsp; ›</button></div><div class="chapter-line"><img class="chapter-thumb" src="goryeo.png" alt="고려 마을 풍경"><div class="chapter-copy"><small>CHAPTER 01</small><h3>918년, 새로운 나라</h3><p>${state.started?`${state.job==='없음'?'낯선 이':state.job} · ${state.visited.length}개의 장면을 경험했어요`:'아직 쓰이지 않은, 당신의 첫 번째 이야기'}</p><div class="progress"><span style="width:${percent()}%"></span></div></div><span class="badge">${state.completed?'완료':state.started?percent()+'%':'시작 가능'}</span></div><div class="section-title" style="margin-top:23px"><h2>시대별 이해도</h2><span class="text-btn">차근차근, 역사를 내 것으로</span></div><div class="era-strip">${ERAS.map(([name],i)=>`<div class="era-item"><b>${name}</b><small>${i===0?understanding():0}%</small><div class="progress"><span style="width:${i===0?understanding():0}%"></span></div></div>`).join('')}</div></section><aside class="review"><span class="eyebrow">${state.wrong.length?'TODAY’S REVIEW':'A MOMENT TO REMEMBER'}</span><h3>${state.wrong.length?'다시 만나면,<br>더 오래 기억하니까.':'살아본 순간이,<br>나의 지식이 되도록.'}</h3><p>${state.wrong.length?`복습할 역사 ${state.wrong.filter(id=>!state.reviewed.includes(id)).length}개가 기다리고 있어요.`:'이야기 속 사건을 경험하고<br>시험에 나오는 핵심까지 기억해 보세요.'}</p><button data-nav="study">${state.wrong.length?'오늘의 복습 시작':'나의 학습 기록'}</button></aside></div><footer class="bottom-note"><span>선택하고, 살아보고, 기억하는 한국사.</span><span>진행 상황은 이 기기에 자동 저장됩니다.</span></footer>`}
function eras(){return pageHeader('당신이 살아갈 시대','CHOOSE YOUR ERA')+`<p class="lead">한 시대의 시작에서, 나만의 이야기를 만나세요.</p><div class="era-list">${ERAS.map(([name,years],i)=>`<section class="era-card"><span class="eyebrow">EPISODE 0${i+1}</span><h2>눈떠보니 ${name}</h2><p>${years}</p>${i===0?'<button class="primary" data-action="play">고려에서 살아보기</button>':`<span class="badge">${icon('lock')} &nbsp; COMING SOON</span>`}</section>`).join('')}</div>`}
function enterStory(){if(!state.visited.includes(state.storyId)&&STORIES[state.storyId])state.visited.push(state.storyId);save()}
function game(){const s=STORIES[state.storyId],p=state.pending;if(!s&&!p){screen=state.storyId==='history'?'history':'home';return renderContent()}const view=p?STORIES[state.choices.at(-1).scene]:s;return `<section class="game" style="background-image:url('${view.background}')"><div class="game-header"><button class="glass" data-nav="home">‹ &nbsp; 이야기 나가기</button><span class="glass">CH.01 &nbsp; ${view.year}년</span><button class="glass" data-action="status">내 상태</button></div><div class="game-stats"><span>♡ &nbsp; 체력 ${state.stats.health}</span><span>◇ &nbsp; 지식 ${state.stats.knowledge}</span><span>◉ &nbsp; ${state.stats.wealth}냥</span></div><div class="scene-title"><small>${view.location}</small><h2>${p?'내가 선택한 길':view.title}</h2></div><div class="dialogue"><div class="speaker">${p?'선택의 결과':view.speaker}</div><p>${p?p.result:view.dialogue}</p>${p?`<div class="result-chips">${Object.entries(p.statChanges).map(([k,v])=>`<span>${statNames[k]} ${v>0?'+':''}${v}${k==='wealth'?'냥':''}</span>`).join('')}${Object.entries(p.relationshipChanges).map(([k,v])=>`<span>${relationNames[k]} ${v>0?'+':''}${v}</span>`).join('')}${p.job?`<span>새 직업 · ${p.job}</span>`:''}</div><button class="primary next" data-action="result-next">이야기 계속</button>`:s.choices?`<div class="choices">${s.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><span>${c.label}</span>${c.hint?`<small>${c.hint}</small>`:''}</button>`).join('')}</div>`:`<button class="primary next" data-action="next">${s.nextStoryId==='arrival'?'눈을 뜬다':'다음 이야기'}</button>`}<div class="sub">${p?'선택과 변화가 저장되었습니다.':'이야기는 역사적 사실을 바탕으로 재구성한 창작입니다.'}</div></div><div class="chapter-progress">${Array.from({length:20},(_,i)=>`<i class="${state.visited.length>i?'on':''}"></i>`).join('')}</div></section>`}
function history(){return pageHeader('방금, 당신이 경험한 역사','HISTORY DISCOVERED')+`<article class="history-card"><span class="eyebrow">역사 카드 001 · 고려</span><h2>918년<br>${HISTORY.title}</h2><img src="goryeo.png" alt="고려의 마을을 바라보는 여행자"><p>${HISTORY.summary}</p><div class="info-note">주인공과 연화·도윤의 이야기는 창작입니다. 고려는 918년 철원에서 건국되었으며, 송악 천도는 919년의 일입니다.</div><p style="font-size:12px;margin-bottom:20px"><a style="color:#617563" href="https://contents.history.go.kr/front/ta/view.do?levelId=ta_m41_0060_0010" target="_blank" rel="noopener noreferrer">역사 내용 참고 · 국사편찬위원회 우리역사넷</a></p><h3>시험에서는 이렇게 기억하세요</h3><div class="keywords">${HISTORY.examKeywords.map(x=>`<span>${x}</span>`).join('')}</div><p style="font-size:13px">건국과 통일을 구분하세요. 고려 건국은 918년, 후삼국 통일은 936년입니다.</p><button class="primary next" data-action="start-quiz">내가 경험한 역사, 문제로 확인하기</button></article>`}
function quiz(){const q=QUESTIONS[activeQ];const done=selected!==null;return pageHeader('이 장면, 시험에서는 어떻게 나올까?','REMEMBER THE MOMENT')+`<section class="quiz"><span class="badge">${quizMode==='review'?'오답 복습':'고려 건국'} · ${activeQ+1} / ${QUESTIONS.length}</span><h2>${q.question.replace('\n','<br>')}</h2><span class="text-btn">직접 만든 연습 문제 · 공식 기출문제가 아닙니다</span>${q.choices.map((x,i)=>`<button class="choice ${done&&i===q.answer?'correct':done&&i===selected?'wrong':''}" data-answer="${i}" ${done?'disabled':''}><span>${['①','②','③','④','⑤'][i]} &nbsp; ${x}</span>${done&&i===q.answer?'✓':''}</button>`).join('')}${done?`<div class="feedback" role="status"><h3>${selected===q.answer?'정답이에요! 그 순간을 기억하고 있네요.':'다시, 그 장면을 떠올려 볼까요?'}</h3><p>${q.explanation}</p><p style="margin-top:12px;color:var(--gold)">${selected===q.answer?'역사 지식 +2 · 학습 기록 저장 완료':'오답노트에 자동 저장했어요.'}</p></div><button class="primary next" data-action="quiz-next">${quizMode==='review'?'복습 기록으로 돌아가기':activeQ<QUESTIONS.length-1?'다음 문제':'나의 첫 번째 챕터 마무리'}</button>`:''}</section>`}
function study(){let body='';if(studyTab==='review'){body=state.wrong.length?state.wrong.map(id=>{const q=QUESTIONS.find(x=>x.questionId===id);return `<div class="list-row"><div><span class="badge">${state.reviewed.includes(id)?'복습 완료':'복습 필요'}</span><h3 style="margin-top:12px">${q.question.split('\n')[0]}</h3><p>고려 건국 · 왕건 · 송악</p></div><button class="primary" data-review="${q.questionId}">다시 풀기</button></div>`}).join(''):`<div class="empty">아직 틀린 역사가 없어요.<br><small>이야기 끝에서 문제를 풀면, 복습할 내용이 이곳에 모여요.</small></div>`}if(studyTab==='quiz')body=QUESTIONS.map((q,i)=>`<div class="list-row"><div><span class="eyebrow">연습 문제 0${i+1}</span><h3 style="margin-top:9px">${['고려를 세운 인물','고려의 첫 천도','건국에서 통일까지'][i]}</h3><p>자체 제작 · ${q.questionId in state.answers?(state.answers[q.questionId]?'정답':'다시 기억하기'):'아직 풀지 않았어요'}</p></div><button class="primary" data-practice="${i}">문제 풀기</button></div>`).join('');if(studyTab==='timeline')body=[['918','고려 건국','왕건이 왕위에 오르고 국호를 고려로 정하다.'],['919','송악 천도','철원에서 왕건의 근거지 송악으로 도읍을 옮기다.'],['936','후삼국 통일','후백제를 멸망시키며 후삼국을 통일하다.']].map(([y,t,d])=>`<div class="list-row"><div><span class="eyebrow">${y}년</span><h3 style="margin-top:10px">${t}</h3><p>${d}</p></div></div>`).join('');if(studyTab==='cards')body=`<div class="collection">${['고려 건국','왕건','광종','서희','강감찬','무신정변'].map((x,i)=>`<div class="collect ${i<2&&state.cards.length?'':'locked'}">${icon(i<2&&state.cards.length?'study':'lock')}<h3>${i<2&&state.cards.length?x:'아직 만나지 못한 역사'}</h3><p>${i<2&&state.cards.length?'CH.01에서 만난 역사':'이야기를 진행하면 열립니다'}</p>${i<2&&state.cards.length?'<button class="text-btn" data-action="card">자세히 보기 ›</button>':''}</div>`).join('')}</div>`;return pageHeader('살아본 순간을, 오래 기억하도록','MY STUDY')+`<div class="tabs">${[['review','오답노트'],['quiz','시험 문제'],['timeline','역사 연표'],['cards','역사 도감']].map(([id,x])=>`<button data-study="${id}" class="${studyTab===id?'selected':''}">${x}</button>`).join('')}</div>${body}`}
function records(){const total=Object.keys(state.answers).length,correct=Object.values(state.answers).filter(Boolean).length;return pageHeader('한 걸음씩, 나의 한국사','MY JOURNEY')+`<div class="stats-grid">${[['스토리 진행률',percent()+'%'],['고려 이해도',understanding()+'%'],['문제 정답률',total?Math.round(correct/total*100)+'%':'—'],['풀어본 문제',total+' / 3'],['경험한 역사 사건',state.cards.length?'1':'0'],['획득 역사 카드',state.cards.length]].map(([t,v])=>`<div class="stat-box"><small>${t}</small><strong>${v}</strong></div>`).join('')}</div><div class="section-title"><h2>나의 고려 인생</h2><button class="text-btn" data-action="status">상태창 보기 ›</button></div><div class="list-row"><div><h3>Lv.${state.completed?4:state.job==='없음'?1:2} · ${state.completed?'시대를 건너는 사람':state.job==='없음'?'낯선 이':'정착한 사람'}</h3><p>918년 · ${state.job} · 최고 재산 ${state.peakWealth}냥</p></div><span class="badge">${state.completed?'첫 장을 마쳤어요':'이야기 진행 중'}</span></div><div class="list-row"><div><h3>획득한 업적</h3><p>${state.completed?'첫 역사의 목격자 · CH.01 완료':state.started?'시간의 여행자 · 고려에 도착':'이야기를 시작하면 업적이 기록됩니다.'}</p></div></div><div class="list-row"><div><h3>나의 선택 ${state.choices.length}개</h3><p>${state.choices.length?state.choices.slice(-3).map(c=>c.label).join(' · '):'아직 선택한 이야기가 없습니다.'}</p></div></div>${state.completed?'<button class="primary next" data-nav="complete">나의 챕터 결말 보기</button>':''}<button class="text-btn" style="margin-top:30px" data-action="restart">새로운 인생 시작하기</button>`}
function complete(){return `<section class="complete"><div class="seal">史</div><div class="eyebrow" style="margin-top:25px">CHAPTER 01 COMPLETE</div><h1>918년, 새로운 나라<br>그리고 나의 첫 번째 삶</h1><p>${state.route==='merchant'?'길 위에서 만난 인연이, 당신의 첫 거래를 열었습니다.':state.route==='village'?'작은 마을에 뿌리내린 당신의 삶이 시작되었습니다.':'새로운 나라의 소식을 직접 보고, 내일을 준비했습니다.'}</p><div class="stats-grid">${[['나의 직업',state.job],['고려 이해도',understanding()+'%'],['내가 내린 선택',state.choices.length+'개'],['역사 카드','1장']].map(([t,v])=>`<div class="stat-box"><small>${t}</small><strong style="font-size:23px">${v}</strong></div>`).join('')}</div><p>오늘은 역사를 외운 날이 아니라,<br>역사 안에서 하루를 살아본 날입니다.</p><button class="primary next" data-nav="teaser">다음 이야기 미리 보기</button><button class="text-btn" style="margin-top:20px" data-nav="home">홈으로 돌아가기</button></section>`}
function teaser(){return `<section class="hero" style="height:650px"><div class="hero-content" style="justify-content:center"><span class="pill">CHAPTER 02 · COMING SOON</span><h2 style="font-size:48px">왕건을 만나다</h2><p>919년, 송악.<br>새로운 도읍에서, 새로운 운명이 기다린다.<br><br>다음 챕터는 준비 중입니다.</p><button class="primary" style="margin-top:30px" data-nav="home">나의 이야기로 돌아가기</button></div></section>`}
function modalHTML(){if(modal==='restart')return `<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="새 인생 시작"><h2>새로운 삶을 시작할까요?</h2><p class="lead" style="margin-top:15px">현재 이야기 진행과 능력치는 초기화됩니다. 학습 기록과 오답노트는 유지됩니다.</p><button class="primary" data-action="confirm-restart">새 이야기 시작</button> <button class="glass" data-action="close">취소</button></section></div>`;return `<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="내 상태"><header><h2>나의 상태</h2><button class="close" data-action="close" aria-label="닫기">×</button></header><p class="lead" style="margin-top:12px">${state.job==='없음'?'Lv.1 낯선 이':'Lv.2 정착한 사람'} · 평민 · ${state.job}</p><div class="stats-grid">${Object.entries(state.stats).map(([k,v])=>`<div class="stat-box"><small>${statNames[k]}</small><strong>${v}${k==='wealth'?'냥':''}</strong></div>`).join('')}</div><h3>함께 살아가는 사람들</h3>${Object.entries(state.relations).map(([k,v])=>`<div class="list-row"><span>${relationNames[k]}</span><span>${v} <small style="color:var(--muted)">/ 100</small></span></div>`).join('')}<p class="text-btn">진행 상황과 관계는 선택할 때마다 자동 저장됩니다.</p></section></div>`}
function renderContent(){return ({home,era:eras,game,history,quiz,study,records,complete,teaser}[screen]||home)()}
function render(){ $('#app').innerHTML=shell(renderContent());if(modal)setTimeout(()=>$('.modal button')?.focus(),0)}
function navigate(to){screen=to;modal=null;render();window.scrollTo(0,0)}
function play(){state.started=true;if(state.completed)return navigate('complete');screen=state.pending?'game':state.storyId==='history'?'history':state.storyId==='quiz'?'quiz':'game';if(screen==='quiz'){activeQ=state.quizIndex;quizMode='chapter';selected=state.quizAnswer??null;}enterStory();render();window.scrollTo(0,0)}
function nextStory(){if(state.storyId==='history'){if(!state.cards.includes('goryeo-918'))state.cards.push('goryeo-918');screen='history';save();render();}else{screen='game';enterStory();render();}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.nav)return navigate(b.dataset.nav);if(b.dataset.study){studyTab=b.dataset.study;return render()}if(b.dataset.choice!==undefined){applyChoice(state,state.storyId,Number(b.dataset.choice));save();return render()}if(b.dataset.answer!==undefined){if(selected!==null)return;selected=Number(b.dataset.answer);const q=QUESTIONS[activeQ],right=selected===q.answer;const previouslyCorrect=state.answers[q.questionId]===true;state.answers[q.questionId]=right;if(quizMode==='chapter')state.quizAnswer=selected;if(!right&&!state.wrong.includes(q.questionId))state.wrong.push(q.questionId);if(right){if(!previouslyCorrect)state.stats.knowledge+=2;if(state.wrong.includes(q.questionId)&&!state.reviewed.includes(q.questionId))state.reviewed.push(q.questionId)}else state.reviewed=state.reviewed.filter(id=>id!==q.questionId);save();return render()}if(b.dataset.review||b.dataset.practice!==undefined){activeQ=b.dataset.review?QUESTIONS.findIndex(q=>q.questionId===b.dataset.review):Number(b.dataset.practice);quizMode='review';selected=null;return navigate('quiz')}switch(b.dataset.action){case'play':return play();case'status':modal='status';return render();case'close':modal=null;return render();case'next':state.storyId=STORIES[state.storyId].nextStoryId;return nextStory();case'result-next':state.pending=null;return nextStory();case'start-quiz':activeQ=0;state.quizIndex=0;state.quizAnswer=null;quizMode=state.storyId==='history'?'chapter':'review';selected=null;if(quizMode==='chapter')state.storyId='quiz';save();return navigate('quiz');case'quiz-next':if(quizMode==='review'){studyTab='review';return navigate('study')}if(activeQ<QUESTIONS.length-1){activeQ++;state.quizIndex=activeQ;state.quizAnswer=null;selected=null;save();return render()}state.completed=true;state.screen='complete';save();return navigate('complete');case'card':return navigate('history');case'restart':modal='restart';return render();case'confirm-restart':{const keep={answers:state.answers,wrong:state.wrong,reviewed:state.reviewed,cards:state.cards};state={...INITIAL(),...keep};modal=null;save();return play()}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render()}if(e.key==='Tab'&&modal){const items=[...document.querySelectorAll('.modal button')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
if(document.modelContext){try{document.modelContext.registerTool({name:'get_history_progress',description:'Read this device’s Korean history game progress, stats, and learning record.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify({storyId:state.storyId,completed:state.completed,stats:state.stats,understanding:understanding(),wrongAnswers:state.wrong.length})}]})});}catch{}}
render();






